export const PICO_NATIVE_FIRMWARE={"RP2040": {"version": "1.29.0", "board": "RPI_PICO", "source": "https://micropython.org/resources/firmware/RPI_PICO-20260824-v1.29.0.uf2", "sourceSHA256": "e1160e602e277d85920adb5fe741435edccba9ba6ecadc85fdab75252eeff4e9", "file": "rp2040-1.29.0.bin", "bytes": 340480, "sha256": "7ddec240b08086c06f35cafef3268bf36ab9102091aee6aa23fa1b1eeeeaa8bc"}, "RP2350": {"version": "1.29.0", "board": "RPI_PICO2", "source": "https://micropython.org/resources/firmware/RPI_PICO2-20260824-v1.29.0.uf2", "sourceSHA256": "6bfc5d110f293870f60150468dfeec8aec5323b57415a0b9a86e6c334e876e93", "file": "rp2350-1.29.0.bin", "bytes": 330496, "sha256": "74ab2137f381ee6ecef5c3a0dbb94f1ab34306b95377bea21d940a213b18143e"}};
export async function loadNativePicoFirmware(chip){const spec=PICO_NATIVE_FIRMWARE[chip];if(!spec)throw Error("Native RP2 çipi geçersiz");const response=await fetch(new URL("./pico-native-fw/"+spec.file,import.meta.url));if(!response.ok)throw Error("RP2 firmware indirilemedi");const bytes=new Uint8Array(await response.arrayBuffer());const hash=Array.from(new Uint8Array(await crypto.subtle.digest("SHA-256",bytes)),b=>b.toString(16).padStart(2,"0")).join("");if(bytes.length!==spec.bytes||hash!==spec.sha256)throw Error("RP2 firmware SHA-256 doğrulaması başarısız");return bytes;}
